// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function testFuzz_property(uint256 depositAmt, uint256 collectAmt) public {
        // Admissible domain: keeper must have balance >= MinSum and >= collectAmt,
        // plus depositAmt > 0 so a deposit changes state.
        depositAmt = bound(depositAmt, 1 ether, 1e30);
        collectAmt = bound(collectAmt, 0, depositAmt);

        address actor = address(0xABCD);
        vm.deal(actor, depositAmt);

        // Setup: set Log to a live helper first (SetLogFile is guarded by !intitalized).
        Recorder rec = new Recorder();
        vm.startPrank(actor);
        c.SetLogFile(address(rec));
        c.Initialized();
        c.Deposit{value: depositAmt}();
        vm.stopPrank();

        uint256 before = c.balances(actor);

        vm.prank(actor);
        c.Collect(collectAmt);

        uint256 afterBal = c.balances(actor);

        // Rule: a successful Collect cannot INCREASE the caller's balance.
        // Reference: afterBal = before - collectAmt <= before.
        // Mutant:   afterBal = before + collectAmt > before for collectAmt > 0.
        assertTrue(afterBal <= before);
    }
}

contract Recorder {
    struct Msg { address sender; uint256 val; string data; }
    uint256 public count;
    function AddMessage(address _adr, uint256 _val, string memory _data) public {
        count++;
    }
    receive() external payable {}
}
